"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type CSSProperties,
  type KeyboardEvent,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatMoney } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import { LAYOUTS, type LayoutId, ROOMS } from "./layout-morph/data";
import { type CardPlace, layOut } from "./layout-morph/layouts";
import { RoomCard } from "./layout-morph/room-card";
import { RoomDetail } from "./layout-morph/room-detail";

const rem = (value: number) => `${value}rem`;

// Cards leave in a ripple: each waits by how far it sits from the card the change started from.
const delayFrom = (origin: CardPlace | undefined, place: CardPlace) =>
  origin
    ? Math.min(0.32, Math.hypot(place.x - origin.x, place.y - origin.y) * 0.012)
    : 0;

/**
 * A gallery of Fernhill rooms that switches between six layouts: grid,
 * masonry, list, stack, carousel and helix. Cards fly to their new places
 * on springs, rippling out from the card in focus, and a card opens into
 * a detail view. Left and right on a card change the layout and keep the
 * card in focus; up, down, Home and End move between cards.
 */
export function LayoutMorph({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const box = useRef<HTMLDivElement>(null);
  const cards = useRef<(HTMLButtonElement | null)[]>([]);
  const [width, setWidth] = useState(40);
  const [layout, setLayout] = useState<LayoutId>("grid");
  const [active, setActive] = useState(0);
  const [origin, setOrigin] = useState(0);
  const [open, setOpen] = useState<number | null>(null);

  useEffect(() => {
    const node = box.current;
    if (!node) return;
    const rootSize =
      Number.parseFloat(getComputedStyle(document.documentElement).fontSize) ||
      16;
    const observer = new ResizeObserver(
      ([entry]) => entry && setWidth(entry.contentRect.width / rootSize),
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const { places, height } = layOut(layout, width, active);
  const before = useRef(places);
  const originPlace = before.current[origin];
  useEffect(() => {
    before.current = places;
  });

  const switchLayout = (next: LayoutId, from = active) => {
    setOrigin(from);
    setLayout(next);
  };
  const focusCard = (index: number) => {
    const next = (index + ROOMS.length) % ROOMS.length;
    setActive(next);
    setOrigin(next);
    cards.current[next]?.focus();
  };
  const closeDetail = () => {
    const index = open;
    setOpen(null);
    if (index !== null) cards.current[index]?.focus();
  };

  const onCardKey = (
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) => {
    const at = LAYOUTS.findIndex((item) => item.value === layout);
    if (event.key === "ArrowRight")
      switchLayout(LAYOUTS[(at + 1) % LAYOUTS.length]!.value, index);
    else if (event.key === "ArrowLeft")
      switchLayout(
        LAYOUTS[(at - 1 + LAYOUTS.length) % LAYOUTS.length]!.value,
        index,
      );
    else if (event.key === "ArrowDown") focusCard(index + 1);
    else if (event.key === "ArrowUp") focusCard(index - 1);
    else if (event.key === "Home") focusCard(0);
    else if (event.key === "End") focusCard(ROOMS.length - 1);
    else return;
    event.preventDefault();
  };

  const layoutLabel =
    LAYOUTS.find((item) => item.value === layout)?.label ?? "";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-3 px-5 pt-5">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Rooms to book by the hour
          </h2>
          <p className="text-sm text-muted-foreground">
            Twelve rooms across five Fernhill buildings. Pick a layout to see
            them another way.
          </p>
        </div>
        <div className="-mx-1 max-w-full overflow-x-auto scroll-fade-effect-x scrollbar-none px-1 py-1">
          <SegmentedControl
            aria-label="Layout"
            options={LAYOUTS}
            value={layout}
            onValueChange={(next) => switchLayout(next)}
          />
        </div>
      </header>

      <div className="px-5 pt-4 pb-5">
        <div
          ref={box}
          className={cn(
            "relative h-(--gallery) w-full perspective-[75rem] motion-safe:transition-all motion-safe:duration-500",
            layout === "carousel" || layout === "helix" || layout === "stack"
              ? "overflow-hidden"
              : "",
          )}

          // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
          style={{ "--gallery": rem(height) } as CSSProperties}
        >
          <ul
            aria-label={`Rooms, ${layoutLabel.toLowerCase()} layout`}
            className="contents"
            inert={open !== null}
          >
            {ROOMS.map((room, index) => {
              const place = places[index]!;
              return (
                <motion.li
                  key={room.id}
                  className={cn(
                    "absolute top-0 left-0 z-(--layer)",
                    place.opacity === 0 && "pointer-events-none",
                  )}
                  initial={false}
                  animate={{
                    x: rem(place.x),
                    y: rem(place.y),
                    width: rem(place.w),
                    height: rem(place.h),
                    rotate: place.rotate,
                    rotateY: place.rotateY,
                    z: rem(place.z),
                    scale: place.scale,
                    opacity: place.opacity,
                  }}
                  transition={
                    reduceMotion
                      ? { duration: 0 }
                      : {
                          type: "spring",
                          stiffness: 260,
                          damping: 28,
                          delay: delayFrom(originPlace, place),
                        }
                  }

                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={{ "--layer": place.layer } as CSSProperties}
                >
                  <Button
                    ref={(node) => {
                      cards.current[index] = node;
                    }}
                    variant="outline"
                    size="sm"
                    tabIndex={index === active ? 0 : -1}
                    aria-hidden={place.opacity === 0 ? true : undefined}
                    aria-label={`${room.name}, ${room.building}, ${formatMoney(room.price)} an hour`}
                    onFocus={() => setActive(index)}
                    onClick={() => {
                      setActive(index);
                      setOpen(index);
                    }}
                    onKeyDown={(event) => onCardKey(event, index)}
                    className="size-full overflow-hidden whitespace-normal"
                  >
                    <RoomCard room={room} row={layout === "list"} />
                  </Button>
                </motion.li>
              );
            })}
          </ul>
          <AnimatePresence>
            {open !== null ? (
              <RoomDetail
                key={ROOMS[open]!.id}
                room={ROOMS[open]!}
                from={places[open]!}
                onClose={closeDetail}
                galleryHeight={height}
              />
            ) : null}
          </AnimatePresence>
        </div>
        <p className="mt-3 text-xs text-muted-foreground" aria-hidden="true">
          On a card, left and right change the layout, up and down move between
          rooms.
        </p>
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

