/** The six ways the gallery can lay the cards out. */
export type LayoutId =
  "grid" | "masonry" | "list" | "stack" | "carousel" | "helix";

/** The layouts in switch order, with their labels. */
export const LAYOUTS: { value: LayoutId; label: string }[] = [
  { value: "grid", label: "Grid" },
  { value: "masonry", label: "Masonry" },
  { value: "list", label: "List" },
  { value: "stack", label: "Stack" },
  { value: "carousel", label: "Carousel" },
  { value: "helix", label: "Helix" },
];

import { type LayoutId, ROOMS } from "./data";

/** Where one card sits in a layout. Lengths are in rem, angles in degrees. */
export interface CardPlace {
  x: number;
  y: number;
  w: number;
  h: number;
  rotate: number;
  rotateY: number;
  z: number;
  scale: number;
  opacity: number;
  layer: number;
}

const GAP = 0.75;

const place = (
  patch: Partial<CardPlace> & Pick<CardPlace, "x" | "y" | "w" | "h">,
): CardPlace => ({
  rotate: 0,
  rotateY: 0,
  z: 0,
  scale: 1,
  opacity: 1,
  layer: 1,
  ...patch,
});

/**
 * Works out every card's place in a layout for a gallery `width` rem wide.
 * `active` is the card the stack, carousel and helix centre on. Returns the
 * places and the height the gallery needs.
 */
export function layOut(layout: LayoutId, width: number, active: number) {
  const count = ROOMS.length;
  const columns = width < 30 ? 2 : width < 46 ? 3 : 4;
  const cardWidth = (width - GAP * (columns - 1)) / columns;

  if (layout === "grid") {
    const h = cardWidth * 1.05;
    const places = ROOMS.map((_, index) =>
      place({
        x: (index % columns) * (cardWidth + GAP),
        y: Math.floor(index / columns) * (h + GAP),
        w: cardWidth,
        h,
      }),
    );
    return { places, height: Math.ceil(count / columns) * (h + GAP) - GAP };
  }
  if (layout === "masonry") {
    const tops = Array.from({ length: columns }, () => 0);
    const places = ROOMS.map((room, index) => {
      const column = tops.indexOf(Math.min(...tops));
      const h = cardWidth * (room.drawing ? 1.35 : 0.7) + (index % 3) * 0.6;
      const spot = place({
        x: column * (cardWidth + GAP),
        y: tops[column]!,
        w: cardWidth,
        h,
      });
      tops[column]! += h + GAP;
      return spot;
    });
    return { places, height: Math.max(...tops) - GAP };
  }
  if (layout === "list") {
    const h = 3.75;
    return {
      places: ROOMS.map((_, index) =>
        place({ x: 0, y: index * (h + 0.5), w: width, h }),
      ),
      height: count * (h + 0.5) - 0.5,
    };
  }
  const w = Math.min(15, width * 0.6);
  const h = w * 1.15;
  if (layout === "stack") {
    const places = ROOMS.map((_, index) => {
      const depth = (index - active + count) % count;
      const shown = depth < 5;
      return place({
        x: width / 2 - w / 2 + depth * 0.5,
        y: 1 + depth * 0.7,
        w,
        h,
        rotate: depth === 0 ? 0 : (depth % 2 === 0 ? 1 : -1) * depth * 1.5,
        scale: 1 - depth * 0.04,
        opacity: shown ? 1 : 0,
        layer: count - depth,
      });
    });
    return { places, height: h + 5 };
  }
  if (layout === "carousel") {
    const places = ROOMS.map((_, index) => {
      const offset = index - active;
      return place({
        x: width / 2 - w / 2 + offset * (w * 0.78),
        y: 1,
        w,
        h,
        scale: offset === 0 ? 1 : 0.86,
        opacity: Math.abs(offset) > 2 ? 0 : 1,
        layer: count - Math.abs(offset),
      });
    });
    return { places, height: h + 2 };
  }
  // The helix winds the cards round a vertical axis, a twelfth of a turn apart, rising as it goes.
  const radius = Math.min(16, width * 0.42);
  const hw = Math.min(11, width * 0.42);
  const hh = hw * 1.15;
  const places = ROOMS.map((_, index) => {
    // The offset wraps, so the cards behind the active one sit on both sides of the helix.
    const offset = ((index - active + count + 6) % count) - 6;
    const turn = (offset * 30 * Math.PI) / 180;
    const front = Math.cos(turn);
    return place({
      x: width / 2 - hw / 2 + Math.sin(turn) * radius,
      y: 5 + offset * 0.9,
      w: hw,
      h: hh,
      rotateY: (turn * 180) / Math.PI,
      z: (front - 1) * radius,
      opacity: front < -0.2 ? 0 : 1,
      layer: Math.round(front * 100) + 100,
    });
  });
  return { places, height: hh + 12 };
}

"use client";

import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import type { Room } from "./data";
import { RoomDrawing } from "./room-drawing";

const HUE_SURFACE = ["bg-chart-1/15", "bg-chart-2/15", "bg-chart-3/15", "bg-chart-4/15", "bg-chart-5/15"];
const HUE_TEXT = [
  "text-chart-1",
  "text-chart-2",
  "text-chart-3",
  "text-chart-4",
  "text-chart-5",
];

/**
 * The inside of one gallery card. As a row it lays out across, with a small
 * drawing. As a tile it shows its drawing large, or its price large when it
 * has no drawing.
 */
export function RoomCard({ room, row }: { room: Room; row: boolean }) {
  if (row) {
    return (
      <span className="flex size-full items-center gap-3 bg-card p-2 text-left">
        <span className="h-full w-16 shrink-0 overflow-hidden rounded-lg">
          {room.drawing ? (
            <RoomDrawing
              drawing={room.drawing}
              hue={room.hue}
              className="size-full"
            />
          ) : (
            <span className={cn("block size-full", HUE_SURFACE[room.hue - 1])} />
          )}
        </span>
        <span className="flex min-w-0 flex-1 flex-col">
          <span className="truncate text-sm font-medium">{room.name}</span>
          <span className="truncate text-xs text-muted-foreground">
            {room.building}
          </span>
        </span>
        <span className="text-sm font-semibold tabular-nums">
          {formatMoney(room.price)} an hour
        </span>
      </span>
    );
  }
  return (
    <span className="flex size-full flex-col bg-card text-left">
      {room.drawing ? (
        <span className="min-h-0 flex-1 overflow-hidden">
          <RoomDrawing
            drawing={room.drawing}
            hue={room.hue}
            className="size-full"
          />
        </span>
      ) : (
        <span
          className={cn(
            "flex flex-1 items-end px-3 pt-3 text-3xl font-semibold tracking-tight tabular-nums",
            HUE_TEXT[room.hue - 1],
            HUE_SURFACE[room.hue - 1],
          )}
        >
          {formatMoney(room.price)}
        </span>
      )}
      <span className="flex flex-col gap-0.5 p-3">
        <span className="truncate text-sm font-medium">{room.name}</span>
        <span className="truncate text-xs text-muted-foreground">
          {room.drawing
            ? `${formatMoney(room.price)} an hour, ${room.building}`
            : `an hour, ${room.building}`}
        </span>
      </span>
    </span>
  );
}

import type { RoomDrawing as Drawing } from "./data";

/** Props for a room drawing. */
export interface RoomDrawingProps {
  drawing: Drawing;
  hue: number;
  className?: string;
}

/**
 * A flat drawing of a room, made of a few shapes in one chart hue: a couch
 * for a treatment room, two chairs for a consult room, mats for a studio,
 * a bench and a plant for a lounge. It is decoration, so it is hidden from
 * screen readers.
 */
export function RoomDrawing({ drawing, hue, className }: RoomDrawingProps) {
  const ink = `var(--chart-${hue})`;
  const soft = `color-mix(in oklch, var(--chart-${hue}) 22%, var(--card))`;
  const mid = `color-mix(in oklch, var(--chart-${hue}) 55%, var(--card))`;
  return (
    <svg
      viewBox="0 0 120 90"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
      className={className}
    >
      <rect width="120" height="90" fill={soft} />
      <rect x="0" y="62" width="120" height="28" fill={mid} opacity="0.45" />
      <rect
        x="78"
        y="12"
        width="28"
        height="26"
        rx="2"
        fill="var(--card)"
        opacity="0.8"
      />
      <path
        d="M92 12v26M78 25h28"
        stroke={ink}
        strokeWidth="1.2"
        opacity="0.5"
      />
      {drawing === "treatment" ? (
        <g>
          <rect x="14" y="48" width="56" height="10" rx="3" fill={ink} />
          <rect x="14" y="42" width="16" height="8" rx="3" fill={mid} />
          <path
            d="M20 58v12M64 58v12"
            stroke={ink}
            strokeWidth="2.5"
            strokeLinecap="round"
          />
        </g>
      ) : null}
      {drawing === "consult" ? (
        <g>
          <rect x="16" y="40" width="18" height="22" rx="4" fill={ink} />
          <rect x="52" y="40" width="18" height="22" rx="4" fill={ink} />
          <rect x="36" y="56" width="14" height="4" rx="1" fill={mid} />
          <path d="M38 60v10M48 60v10" stroke={ink} strokeWidth="1.5" />
        </g>
      ) : null}
      {drawing === "studio" ? (
        <g>
          <rect x="10" y="66" width="32" height="7" rx="3" fill={ink} />
          <rect x="48" y="66" width="32" height="7" rx="3" fill={mid} />
          <circle cx="98" cy="62" r="10" fill={ink} />
          <rect x="10" y="14" width="4" height="46" rx="1" fill={mid} />
        </g>
      ) : null}
      {drawing === "waiting" ? (
        <g>
          <rect x="10" y="50" width="62" height="9" rx="3" fill={ink} />
          <path
            d="M16 59v11M66 59v11"
            stroke={ink}
            strokeWidth="2.5"
            strokeLinecap="round"
          />
          <rect x="88" y="56" width="12" height="14" rx="2" fill={mid} />
          <circle cx="94" cy="48" r="9" fill={ink} />
        </g>
      ) : null}
    </svg>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { formatMoney } from "../../lib/format";
import { CheckIcon, XIcon } from "../../parts/icons";
import type { Room } from "./data";
import type { CardPlace } from "./layouts";
import { RoomDrawing } from "./room-drawing";

/** Props for the detail view a card grows into. */
export interface RoomDetailProps {
  room: Room;
  /** Where the card was, so the detail grows out of it and shrinks back into it. */
  from: CardPlace;
  onClose: () => void;
  /** The gallery's height in rem. The detail grows to it, up to 26rem. */
  galleryHeight: number;
}

const rem = (value: number) => `${value}rem`;

/**
 * One room in full, grown out of its card to cover the gallery. Focus moves
 * to the close button, Escape closes, and the parent returns focus to the
 * card.
 */
export function RoomDetail({ room, from, onClose, galleryHeight }: RoomDetailProps) {
  const reduceMotion = useReducedMotion();
  const closeRef = useRef<HTMLButtonElement>(null);
  const [requested, setRequested] = useState(false);
  useEffect(() => closeRef.current?.focus(), []);
  const start = {
    left: rem(from.x),
    top: rem(from.y),
    width: rem(from.w),
    height: rem(from.h),
    borderRadius: "0.75rem",
  };
  return (
    <motion.div
      role="dialog"
      aria-modal="true"
      aria-label={room.name}
      initial={reduceMotion ? false : start}
      animate={{
        left: "0rem",
        top: "0rem",
        width: "100%",
        height: rem(Math.min(galleryHeight, 26)),
        borderRadius: "1rem",
      }}
      exit={reduceMotion ? { opacity: 0 } : start}
      transition={
        reduceMotion
          ? { duration: 0 }
          : { type: "spring", stiffness: 300, damping: 32 }
      }
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.stopPropagation();
          onClose();
        }
      }}
      className="absolute z-50 flex flex-col overflow-hidden border border-border bg-card shadow-xl @xl:flex-row"
    >
      <div className="relative min-h-40 flex-1 overflow-hidden">
        {room.drawing ? (
          <RoomDrawing
            drawing={room.drawing}
            hue={room.hue}
            className="absolute inset-0 size-full"
          />
        ) : (
          <span className="absolute inset-0 bg-muted" />
        )}
      </div>
      <div className="flex flex-col gap-3 p-5 @xl:w-72">
        <div className="flex items-start justify-between gap-3">
          <div>
            <h3 className="text-lg font-semibold">{room.name}</h3>
            <p className="text-sm text-muted-foreground">{room.building}</p>
          </div>
          <Button
            ref={closeRef}
            variant="ghost"
            size="icon"
            aria-label="Close"
            onClick={onClose}
          >
            <XIcon aria-hidden="true" className="size-4" />
          </Button>
        </div>
        <p className="text-sm">{room.about}</p>
        <dl className="grid grid-cols-2 gap-2 text-sm">
          <dt className="text-muted-foreground">Price</dt>
          <dd className="font-medium">{formatMoney(room.price)} an hour</dd>
          <dt className="text-muted-foreground">Seats</dt>
          <dd className="font-medium">{room.seats}</dd>
        </dl>
        <Button
          className="mt-auto"
          variant={requested ? "secondary" : "default"}
          aria-pressed={requested}
          onClick={() => setRequested((value) => !value)}
        >
          {requested ? (
            <CheckIcon aria-hidden="true" className="size-4" />
          ) : null}
          {requested ? "Requested for tomorrow" : "Request this room"}
        </Button>
        <p role="status" className="sr-only">
          {requested ? `${room.name} requested for tomorrow.` : ""}
        </p>
      </div>
    </motion.div>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

